import{_ as r,C as d,o,c as n,a5 as i,b as l,w as t,a as s,E as h,a6 as p,j as c}from"./chunks/framework.BEZBAInb.js";const A=JSON.parse('{"title":"對話資料","description":"","frontmatter":{"title":"對話資料","order":1},"headers":[],"relativePath":"tc/2.4/tutorial/core/shot-and-dialogue.md","filePath":"tc/2.4/tutorial/core/shot-and-dialogue.md","lastUpdated":1788455378000}'),_={name:"tc/2.4/tutorial/core/shot-and-dialogue.md"};function D(u,a,K,E,S,N){const e=d("Mermaid");return o(),n("div",null,[a[1]||(a[1]=i('<h1 id="knd-shot-以及-knd-dialogue" tabindex="-1">KND_Shot 以及 KND_Dialogue <a class="header-anchor" href="#knd-shot-以及-knd-dialogue" aria-label="Permalink to &quot;KND_Shot 以及 KND_Dialogue&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>本章節將介紹 Konado 的兩個核心類別：KND_Shot 和 KND_Dialogue。這兩個類別是 Konado 的核心，用於表示對話鏡頭與對話。如果你希望深入了解 Konado 的架構原理，理解這兩個類別非常重要。在充分理解這兩個類別的基礎上，你可以根據自身需求對它們進行擴充與修改。</p><h2 id="knd-shot" tabindex="-1">KND_Shot <a class="header-anchor" href="#knd-shot" aria-label="Permalink to &quot;KND_Shot&quot;">​</a></h2><h3 id="定義" tabindex="-1">定義 <a class="header-anchor" href="#定義" aria-label="Permalink to &quot;定義&quot;">​</a></h3><p>KND_Shot 是 Konado 的一個核心類別，用於表示一個對話鏡頭。</p><p>鏡頭是影視與動畫製作中的基本概念，表示一段連續畫面，通常包含一系列影格。在這裡，KND_Shot 類別用於表示一個對話鏡頭，其中包含一系列對話。</p><p>也可以用書本的概念來理解：一個鏡頭就是一個小章節，而一個對話鏡頭就是小章節中的對話。</p><p>KND_Shot 負責組織零散的 KND_Dialogue 資料物件，並按照一定順序排列它們，以便播放時能依照指定順序播放。</p><p>當然，與電影鏡頭不同，KND_Shot 不一定表示連續、線性的故事，而是可能由多個 branch 分支組成。每個分支都包含一系列對話，並搭配 choice 實作多選分支，讓使用者選擇不同的對話路徑。</p><h3 id="knd-shot-與-konadoscript-的關係" tabindex="-1">KND_Shot 與 KonadoScript 的關係 <a class="header-anchor" href="#knd-shot-與-konadoscript-的關係" aria-label="Permalink to &quot;KND_Shot 與 KonadoScript 的關係&quot;">​</a></h3><p>在使用過程中你不難發現，預設情況下 KND_Shot 不需要手動建立，而是由 KonadoScript 自動建立並自動更新資料。這是因為我們採用了自訂的 KonadoScript 語法，並使用 KonadoScript 解析器解析腳本檔案，將來源檔案的行解析為 KND_Dialogue 物件，然後依照一定規則組織成 KND_Shot 物件。</p><p>如果用流程圖表示，從 KonadoScript 到多個 KND_Dialogue，再到 KND_Shot 的過程大致如下：</p>',13)),(o(),l(p,null,{default:t(()=>[h(e,{id:"mermaid-39",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%22KonadoScript%E4%BE%86%E6%BA%90%E6%AA%94%E6%A1%88%22%5D%20--%3E%20B%5B%22%E8%A7%A3%E6%9E%90%E5%99%A8%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E7%94%9F%E6%88%90KND_Dialogue%E7%89%A9%E4%BB%B6%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22%E6%8C%89%E8%A6%8F%E5%89%87%E7%B5%84%E7%B9%94%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22%E8%87%AA%E5%8B%95%E5%BB%BA%E7%AB%8B%2F%E6%9B%B4%E6%96%B0KND_Shot%22%5D%0A%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=c("p",null,"如果你想詳細了解 KonadoScript 的解析過程，可以參考 KonadoScript 的相關文件以及解析器原始碼。",-1))])}const m=r(_,[["render",D]]);export{A as __pageData,m as default};
